// open.js — OPEN VOCABULARY. The architecture void has never had, and the one thing that could
// break the [[fixed-vocabulary-ceiling]]: a genotype→phenotype map whose set of possible functions
// is not a fixed menu but is GENERATED by program composition (the CPPN / indirect-encoding spirit,
// Stanley — named in the literature as the ALife closest to real open-ended evolution).
//
// THE MECHANISM
//   genome = a short program (list of instructions) over K registers. Running it yields a KEY
//   (a K-vector of integers). The world is cells each holding a LOCK (a K-vector). An organism
//   HARVESTS its cell only if its key matches the lock (L1 distance <= TOL). Energy/upkeep/repro
//   as in the vetted niche.js substrate.
//   • There is NO menu of functions. A key is any reachable lattice point; the space of keys is
//     open (bounded only by a register clamp, ~10^5 points — effectively open at our timescales).
//   • Reaching a key FAR from the origin requires COMPOSING more instructions — so program
//     complexity has a REASON to grow (unlike the fixed menu, where 8 parts is the whole world).
//   • NICHE CONSTRUCTION returns, now in open space: an organism can spend energy to set its cell's
//     lock to its OWN key — plant ground shaped like itself. This is the pepper in an open world.
//   • CROWDING = negative frequency dependence: harvest yield is divided by how many living
//     organisms share your exact key. Being common is costly → radiating into an UNoccupied key
//     region pays → adaptive radiation is the incentive, not a decree.
//
// THE CONTROL (the whole point — isolates ONE variable). menuSize M>0 bottlenecks the phenotype:
//   key := MENU[ hash(fullkey) % M ], a fixed set of M points. Identical genomes, identical
//   everything — only the genotype→phenotype IMAGE is capped at M. So "open vs capped image" is
//   the single manipulated variable, exactly the fixed-vocabulary hypothesis under test.
//
// THE HONEST TRAP (pre-registered, from [[proxy-metric-trap]] and silica): an open vocabulary can
//   just DIFFUSE — endless distinct keys that are neutral drift, high novelty + zero complexity +
//   no stable coexistence (silica's exact failure). So novelty alone is NOT the win. I measure
//   THREE things and the win requires all three:
//     1. distinctNiches — distinct keys among the LIVING (breadth). Drift inflates this alone.
//     2. stableNiches   — keys occupied continuously for >= STABLE_AGE ticks (real niches, not churn).
//     3. progComplexity — mean number of EFFECTIVE (key-affecting) instructions per organism. The
//        ratchet signal: do programs get more elaborate to reach new niches, or stay trivial?
//   Open-endedness-ish = stableNiches AND progComplexity both rise and keep rising. Diffusion =
//   distinctNiches rises while stableNiches/progComplexity stay flat. Plateau = all three settle.
//
// Pure, seeded, headless. Same discipline as ceiling.js / niche.js.

'use strict';

function rng(seed) {
  let a = seed >>> 0;
  return () => { a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

// instruction set — NO free constants, so reaching a distant key needs COMPOSITION (length↔reach).
// 0 INC t     r[t]+=1        1 DEC t     r[t]-=1
// 2 DBL t     r[t]*=2        3 ADDr t s  r[t]+=r[s]
// 4 NEG t     r[t]=-r[t]
const N_OPS = 5;

class Open {
  constructor(opts = {}) {
    this.cols = opts.cols || 50;
    this.rows = opts.rows || 50;
    this.CELLS = this.cols * this.rows;
    this.K = opts.registers || 3;          // key dimensionality
    this.CAP = opts.cap ?? 24;             // register clamp → key lattice is (2*CAP+1)^K, bounded-open
    this.TOL = opts.tol ?? 0;              // L1 match tolerance (0 = exact)
    this.menuSize = opts.menuSize ?? 0;    // 0 = OPEN (treatment); >0 = capped image (control)
    this.construct = opts.construct ?? false;

    this.UPKEEP = opts.upkeep ?? 1;
    this.YIELD = opts.yield ?? 4;
    this.REPRO_COST = opts.reproCost ?? 12;
    this.REPRO_THRESH = opts.reproThresh ?? 16;
    // CONSERVED ENERGY (2026-07-24, Jiggy's energy-conservation idea). Default OFF = original infinite
    // source. When on, the world holds a FIXED total energy: harvest DRAWS from a global pool, and every
    // sink (upkeep, death remains, build cost, reproduction loss) RETURNS energy to the pool instead of
    // destroying it. Total = pool + sum(org energy) is invariant (verified by the experiment's canary).
    // The point: energy is finite, so a better harvester deprives others — variation becomes NON-neutral.
    this.conserveEnergy = opts.conserveEnergy ?? false;
    this.pool = opts.energyPool ?? 0;
    // OPEN / DISSIPATIVE mode (2026-07-24): energy FLOWS THROUGH. Each tick the pool gains `influx` from
    // outside (the sun); when `dissipate` is on, sinks (upkeep etc.) LEAVE the system as heat instead of
    // returning to the pool. Closed conserved = influx 0 + dissipate off. This separates "throughput/flow
    // drives building" from the boring "there just wasn't enough energy": sweep influx and see if the
    // complexity climb scales with the FLOW RATE at bounded standing energy.
    this.influx = opts.influx ?? 0;
    this.dissipate = opts.dissipate ?? false;
    // signal-shaped-noise null (see step()): shuffle lock↔cell assignment every scramblePeriod ticks.
    this.scrambleLocks = opts.scrambleLocks ?? false;
    this.scramblePeriod = opts.scramblePeriod ?? 50;
    this.MUT_PT = opts.mutPt ?? 0.08;
    this.MUT_INDEL = opts.mutIndel ?? 0.10;
    this.LEN_MAX = opts.lenMax ?? 24;
    this.CROWD = opts.crowd ?? 6;          // yield ~ 1/(1+share/CROWD): frequency-dependent
    this.BUILD_COST = opts.buildCost ?? 4;
    this.BUILD_THRESH = opts.buildThresh ?? 8;
    this.BUILD_P = opts.buildP ?? 0.4;
    this.REVERT_P = opts.revertP ?? 0.002;
    this.STABLE_AGE = opts.stableAge ?? 400; // a key must persist this long to count as a "stable niche"

    this.rand = rng(opts.seed || 1);

    // fixed menu points for the control: M random lattice keys (deterministic from seed)
    this.MENU = [];
    for (let i = 0; i < (this.menuSize || 0); i++) {
      const v = []; for (let k = 0; k < this.K; k++) v.push((this.rand() * (2 * this.CAP + 1) | 0) - this.CAP);
      this.MENU.push(v);
    }

    // locks: a patchy landscape of REACHABLE keys. Each patch's lock is the key of a random short
    // program (so it can actually be matched by an evolvable genome — an unreachable random lattice
    // point would just starve everyone). This is niche.js's patchy field lifted into key space, and
    // it keeps the seed programs (this.patchProg) so organisms can be born already-fed.
    this.lock = new Array(this.CELLS);
    this.patchProg = new Array(this.CELLS);
    const bx = 6, by = 6, pKey = {}, pProg = {};
    for (let y = 0; y < this.rows; y++) for (let x = 0; x < this.cols; x++) {
      const px = (x / bx) | 0, py = (y / by) | 0, key = px + ',' + py;
      if (pKey[key] === undefined) {
        const len = 1 + this._rint(3), g = []; for (let j = 0; j < len; j++) g.push(this._randInstr());
        pProg[key] = g; pKey[key] = this._run(g).key;
      }
      const c = y * this.cols + x;
      this.lock[c] = pKey[key].slice(); this.patchProg[c] = pProg[key];
    }
    this.builtBy = new Int32Array(this.CELLS).fill(-1);

    this.grid = new Int32Array(this.CELLS).fill(-1);
    this.orgs = [];
    this.nextLineage = 1;
    this.tick = 0; this.births = 0; this.deaths = 0; this.builds = 0;
    // key-occupancy ledger: keyStr -> {since: tick first continuously occupied, seen: last tick present}
    this.keySince = new Map();
    this._seed(opts.seedOrganisms || 60);
  }

  _rint(n) { return (this.rand() * n) | 0; }
  _clamp(v) { return v < -this.CAP ? -this.CAP : v > this.CAP ? this.CAP : v; }

  _seed(k) {
    for (let i = 0; i < k; i++) {
      const cell = this._rint(this.CELLS);
      if (this.grid[cell] !== -1) continue;
      // born already matched to the local patch (its program is exactly what made that lock), so
      // the founder population is fed and radiation can start instead of an instant crash.
      const g = this.patchProg[cell].map(instr => ({ ...instr }));
      this._place(cell, g, 8 + this.rand() * 6, this.nextLineage++);
    }
  }

  _randInstr() {
    const op = this._rint(N_OPS);
    return { op, t: this._rint(this.K), s: this._rint(this.K) };
  }

  // run the program → key vector. Also returns effectiveLen: instructions that actually changed a
  // register given the run (the "expressed" program — trailing/no-op instructions don't count).
  _run(genome) {
    const r = new Array(this.K).fill(0);
    let eff = 0;
    for (const g of genome) {
      const before = r[g.t];
      switch (g.op) {
        case 0: r[g.t] = this._clamp(r[g.t] + 1); break;
        case 1: r[g.t] = this._clamp(r[g.t] - 1); break;
        case 2: r[g.t] = this._clamp(r[g.t] * 2); break;
        case 3: r[g.t] = this._clamp(r[g.t] + r[g.s]); break;
        case 4: r[g.t] = this._clamp(-r[g.t]); break;
      }
      if (r[g.t] !== before) eff++;
    }
    let key = r;
    if (this.menuSize) {                 // CONTROL: bottleneck the image through M fixed points
      let h = 2166136261 >>> 0;
      for (const x of r) { h ^= (x + 64); h = Math.imul(h, 16777619) >>> 0; }
      key = this.MENU[h % this.menuSize];
    }
    return { key, eff };
  }

  _keyStr(key) { return key.join(','); }

  _place(cell, genome, energy, lineage) {
    const o = { cell, genome, energy, age: 0, lineage };
    const { key, eff } = this._run(genome);
    o.key = key; o.keyStr = this._keyStr(key); o.eff = eff;
    this.grid[cell] = this.orgs.length;
    this.orgs.push(o);
    return o;
  }

  _neighbors(cell) {
    const x = cell % this.cols, y = (cell / this.cols) | 0, out = [];
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= this.cols || ny >= this.rows) continue;
      out.push(ny * this.cols + nx);
    }
    return out;
  }

  _match(key, lock) {
    let d = 0; for (let k = 0; k < this.K; k++) { d += Math.abs(key[k] - lock[k]); if (d > this.TOL) return false; }
    return true;
  }

  _mutate(g) {
    g = g.map(i => ({ ...i }));
    for (const i of g) if (this.rand() < this.MUT_PT) { const m = this._randInstr(); i.op = m.op; i.t = m.t; i.s = m.s; }
    if (this.rand() < this.MUT_INDEL) {
      if (this.rand() < 0.5 && g.length < this.LEN_MAX) g.splice(this._rint(g.length + 1), 0, this._randInstr());
      else if (g.length > 1) g.splice(this._rint(g.length), 1);
    }
    return g;
  }

  step() {
    this.tick++;
    // SIGNAL-SHAPED NOISE (reticuli's two-sided null, 2026-07-24): permute the fitness assignment.
    // Every scramblePeriod ticks, SHUFFLE which lock sits at which cell — identical set of targets,
    // identical match difficulty, identical selection pressure and compute, but the SPATIAL SIGNAL
    // (a stable niche you can settle into) is destroyed. Selection still acts; there's just nothing
    // real to adapt TO. This is the null that shares all machinery except the signal's content.
    if (this.scrambleLocks && this.scramblePeriod > 0 && this.tick % this.scramblePeriod === 0) {
      for (let i = this.CELLS - 1; i > 0; i--) {
        const j = this._rint(i + 1);
        const tl = this.lock[i]; this.lock[i] = this.lock[j]; this.lock[j] = tl;
        const tp = this.patchProg[i]; this.patchProg[i] = this.patchProg[j]; this.patchProg[j] = tp;
        const tb = this.builtBy[i]; this.builtBy[i] = this.builtBy[j]; this.builtBy[j] = tb;
      }
    }
    // built locks slowly revert (unmaintained niches decay)
    if (this.REVERT_P > 0) {
      const tries = Math.min(this.CELLS, this.orgs.length + 64);
      for (let i = 0; i < tries; i++) {
        const c = this._rint(this.CELLS);
        if (this.builtBy[c] !== -1 && this.rand() < this.REVERT_P) { this.lock[c] = new Array(this.K).fill(0); this.builtBy[c] = -1; }
      }
    }
    // OPEN system: energy pours in from outside each tick (bounded standing pool via dissipation below).
    if (this.conserveEnergy && this.influx) this.pool += this.influx;
    const N = this.orgs.length;
    if (N === 0) return;
    // crowding census: how many living organisms share each key
    const share = new Map();
    for (const o of this.orgs) if (!o.dead) share.set(o.keyStr, (share.get(o.keyStr) || 0) + 1);

    const start = this.tick % N;
    for (let j = 0; j < N; j++) {
      const o = this.orgs[(start + j) % N];
      if (!o || o.dead) continue;
      const matched = this._match(o.key, this.lock[o.cell]);
      const crowd = share.get(o.keyStr) || 1;
      const want = matched ? this.YIELD / (1 + crowd / this.CROWD) : 0;   // frequency-dependent yield
      // conserved: harvest is capped by what's actually in the shared pool (finite → real competition).
      const gain = this.conserveEnergy ? Math.min(want, this.pool) : want;
      if (this.conserveEnergy) this.pool -= gain;
      o.energy += gain;
      // upkeep leaves the organism; conserved → it returns to the pool (dissipated, reusable), not destroyed.
      o.energy -= this.UPKEEP;
      if (this.conserveEnergy && !this.dissipate) this.pool += this.UPKEEP;
      o.age++;

      // niche construction — plant own key as the local lock (open-space pepper)
      if (this.construct && o.energy >= this.BUILD_THRESH && this.rand() < this.BUILD_P) {
        if (this._keyStr(this.lock[o.cell]) !== o.keyStr) {
          this.lock[o.cell] = o.key.slice();
          this.builtBy[o.cell] = o.lineage;
          o.energy -= this.BUILD_COST;
          if (this.conserveEnergy && !this.dissipate) this.pool += this.BUILD_COST;   // build cost returns to environment
          this.builds++;
        }
      }

      if (o.energy <= 0) {
        if (this.conserveEnergy && !this.dissipate) this.pool += o.energy;   // return remainder (may be a small debt) — keeps total exact
        o.dead = true; this.grid[o.cell] = -1; this.deaths++; continue;
      }

      if (o.energy >= this.REPRO_THRESH) {
        const free = this._neighbors(o.cell).filter(c => this.grid[c] === -1);
        if (free.length) {
          const cost = this.REPRO_COST;
          if (o.energy >= cost) {
            const child = this._mutate(o.genome);
            const cell = free[this._rint(free.length)];
            o.energy -= cost;
            this._place(cell, child, cost * 0.6, o.lineage);
            // repro is lossy (child gets 60% of cost); conserved → the lost 40% returns to the pool.
            if (this.conserveEnergy && !this.dissipate) this.pool += cost * 0.4;
            this.births++;
          }
        }
      }
    }

    if (this.orgs.length > this.CELLS * 3) {
      const alive = this.orgs.filter(o => !o.dead);
      this.orgs = alive; this.grid.fill(-1);
      for (let i = 0; i < alive.length; i++) this.grid[alive[i].cell] = i;
    }

    // update the key-occupancy ledger for the stable-niche metric
    const nowKeys = new Set();
    for (const o of this.orgs) if (!o.dead) nowKeys.add(o.keyStr);
    for (const ks of nowKeys) { if (!this.keySince.has(ks)) this.keySince.set(ks, { since: this.tick, seen: this.tick }); else this.keySince.get(ks).seen = this.tick; }
    // forget keys absent for a while (so "stable" means currently+continuously occupied)
    for (const [ks, rec] of this.keySince) if (rec.seen < this.tick) this.keySince.delete(ks);
  }

  stats() {
    const living = this.orgs.filter(o => !o.dead);
    const n = living.length || 1;
    const keys = new Set(), lens = []; let effSum = 0;
    for (const o of living) { keys.add(o.keyStr); lens.push(o.genome.length); effSum += o.eff; }
    // stable niches: keys occupied continuously for >= STABLE_AGE
    let stable = 0;
    for (const [, rec] of this.keySince) if (this.tick - rec.since >= this.STABLE_AGE) stable++;
    let builtCells = 0; for (let c = 0; c < this.CELLS; c++) if (this.builtBy[c] !== -1) builtCells++;
    return {
      tick: this.tick, pop: living.length, menuSize: this.menuSize,
      distinctNiches: keys.size,                          // breadth (drift inflates this alone)
      stableNiches: stable,                               // niches held >= STABLE_AGE (real, not churn)
      progComplexity: +(effSum / n).toFixed(2),           // mean effective (key-affecting) instructions
      rawLen: +(lens.reduce((a, b) => a + b, 0) / n).toFixed(2),
      builtFrac: +(builtCells / this.CELLS).toFixed(3),
      builds: this.builds, births: this.births, deaths: this.deaths,
    };
  }

  view() {
    // colour by key hash so distinct functions read as distinct hues
    return this.orgs.filter(o => !o.dead).map(o => {
      let h = 2166136261 >>> 0; for (const x of o.key) { h ^= (x + 64); h = Math.imul(h, 16777619) >>> 0; }
      return { cell: o.cell, hue: h % 360, built: this.builtBy[o.cell] !== -1 };
    });
  }
}

if (typeof module !== 'undefined' && module.exports) module.exports = { Open };
if (typeof window !== 'undefined') { window.Open = Open; }
